`int residence = addressSum / relatives;` 計算平均數，不能保證絕對距離總和最小。先排序，再讓 residence 取中位數；例如 1、2、100 選 2 的總和為 99，選 34 為 131。偶數筆取其中一個中間值即可。

```cpp
#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int cases;
    cin >> cases;
    while (cases--) {
        int relatives;
        cin >> relatives;
        vector<int> addresses(relatives);
        int addressSum = 0;
        for (int &address : addresses) {
            cin >> address;
            addressSum += address;
        }
        sort(addresses.begin(), addresses.end());
        int residence = addresses[relatives / 2];
        int distanceSum = 0;
        for (int address : addresses)
            distanceSum += abs(address - residence);
        cout << distanceSum << '\n';
    }
}
